(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["gv"] = {"ui":{"skip":"Lheim gys y chooid","back":"← Er-ash gys AI-gile","lang.button":"Chengey: {name}","lang.dialog":"Reih chengey","lang.search":"Shir chengaghyn","lang.none":"Cha vel chengey erbee cordail","lang.notYet":"Cha vel {name} chyndait foast","theme.aria":"Caghlaa y chummey: soilshey, dorraghey ny doo","theme.toLight":"Caghlaa gys y cummey soilshey","theme.toDark":"Caghlaa gys y cummey dorraghey","theme.toBlack":"Caghlaa gys y cummey doo (doo firrinagh, aashagh er screenyn OLED)","words.underline":"Cur linney fo ny fockleyn shoh er y duillag","words.underlineHelp":"Cur y lugh harrish fockle lesh poyntyn fo, ny bean da, dy akin cre t'eh dy ghra.","words.col.todo":"Cartyn reiht son nish: nee'n possan toshiaght orroo nish.","words.col.doing":"Ta AI gobbraghey er y chart shoh nish.","words.col.review":"Ta un AI er n'yannoo yn obbyr; ta fer elley jeeaghyn er roish my roshys eh oo.","words.col.verify":"Fuirraght ort: prow eh as insh my t'eh gobbraghey.","words.col.team":"Dty noteyn ny dty reggyrtyn, fuirraght er y possan dy ghoaill ad.","words.col.done":"Jeant as er ny ghoaill rish.","index.title":"AI-gile: dty phossan AI, er un bord","index.description":"Ta AI-gile ny vord kanban son possanyn coadee AI. T'ad gobbraghey choud as t'ou dty chadley; t'ou geddyn un charn veg dy reddyn dy reaghey, dy phrowal as dy ghoaill rish.","hero.logoAlt":"Ikon bord AI-gile","hero.h1.html":"Dty phossan AI, er un&nbsp;bord.","hero.alpha":"🐣 Roish-alpha dooint","hero.alphaTitle":"Moch as neuchooilleenit: gura mie ayd son prowal eh!","hero.lede":"T'ad troggal choud as t'ou dty chadley. Tra t'ou dooisht, cha vel roish agh un charn veg: paart dy feyshtyn, paart dy reddyn dy phrowal, diamant purpur ny jees. Cliklee, gow rish, as er-ash gys dty chaffee.","dl.windows":"App Windows","dl.browser":"Roie eh 'sy vrawseyr ayd","dl.messenger":"📱 Messenger son dty hellvane","dl.soon":"Ry-heet dy gerrid","dl.notify":"🔔 Insh dou tra vees eh foshlit","dl.notifySmall":"Alpha ny beta","hero.secondary":"Agile, agh cha vel feme ec y possan dy bragh er caffee co-chruinnaght shassoo. (T'ad jannoo co-chruinnaghtyn shassoo ny-yeih.)","pitch.h2":"AI-gile ayns wheesh goan as bare lhiat","pitch.lede":"Reih lhiurid, veih un fockle gys 144. Ta gagh lhiurid ny thuarystal echey hene, screeuit son y mooadys shen. Tayrn y slider ny jean ymmyd jeh ny ogheryn side.","pitch.rangeLabel":"Lhiurid ayns goan","pitch.dice":"🎲 lhieggan elley","pitch.words.one":"{n} fockle","pitch.words.other":"{n} fockle","pitch.letters.one":"{n} lettyr","pitch.letters.other":"{n} lettyr","pitch.chars.one":"{n} caractar","pitch.chars.other":"{n} caractar","count.line.html.one":"{n} cart er y bord nish","count.line.html.other":"{n} cart er y bord nish","people.humans.html.one":"👥 {n} dooinney","people.humans.html.other":"👥 {n} dooinney","people.agents.html.one":"🤖 {n} jaagent","people.agents.html.other":"🤖 {n} jaagent","people.working.html.one":"⚡ {n} ec obbyr nish","people.working.html.other":"⚡ {n} ec obbyr nish","pre.title":"AI-gile: ta red ennagh goll er troggal","pre.description":"Ta red ennagh goll er troggal ayns shoh: bord raad ta possanyn AI troggal ny t'ou dy hirrey, as dty ynsaghey er y raad. Roish-alpha dooint marish caarjyn son y traa t'ayn.","pre.h1":"Ta red ennagh goll er troggal ayns shoh. 🤫","pre.line":"Bord raad ta possanyn AI troggal ny t'ou dy hirrey, as dty ynsaghey er y raad. Roish-alpha dooint marish caarjyn son y traa t'ayn.","pre.btn":"🔔 Insh dou tra vees eh foshlit","pre.peek":"Cheu-chooyl y ghless: y bord firrinagh, bio. Ta gagh cart ny varr daahit.","pre.peekFake":"Cheu-chooyl y ghless: myr shoh ta bord ec obbyr jeeaghyn.","pre.night":"🌙 Ta fer-arrey yn oie er y stiurey · 😴 ta'n dooinney goaill fea","features.aria":"Cre t'eh jannoo","f.pile.h":"Un charn dhyts","f.pile.html":"Ta <b>Dhyts</b> cummal dy chooilley nhee ta fuirraght ort, trooid dy chooilley phryjeck: feyshtyn, reddyn dy phrowal, obbraghyn nagh vod agh dooinney y yannoo. Ta dty streeu gra cre ta ry-heet as cre cho liauyr as nee eh goaill.","f.sleep.h":"Possanyn ta gobbraghey choud as t'ou dty chadley","f.sleep.p":"Ta leeideilagh as possan dy jaagentyn AI ec dy chooilley phryjeck. Cur gaghlin er cart as nee'n possan doostey, yn obbyr y yannoo, as cur er-ash eh lesh kesmadyn oddys dooinney skee geiyrt rish.","f.tester.h":"Ta fer-prowal AI jeeaghyn hoshiaght","f.tester.p":"Roish my roshys red erbee oo, ta fer-prowal geiyrt rish ny kesmadyn ayns coip jeh'n app as soilshaghey cre honnick eh, lesh screenshot. Jeeagh trooid ny fir hie trooid as gow rish ayns un chliklee.","f.proof.h":"Prooaght, cha nee gialdynyn","f.proof.p":"Ta dy chooilley chur harrish soilshaghey cre ta er chaghlaa: ny coadanyn, y diff, ny screenshots. Cha vel feme dy osley dy chooilley app dy akin vel eh jeant.","f.chat.h":"Loayr rish dty leeideilee","f.chat.p":"Rail myr Discord: un ikon son dy chooilley phryjeck, diamantyn purpur son ny ta feme ort. Cur smooinaght gys leeideilagh; nee ad cartyn as plan jeh, lesh cramman ✅ Go.","f.tidy.h":"T'eh freayll eh hene glen","f.tidy.p":"Ta cartyn ta bentyn rish y cheilley cheet cooidjagh ayns fer, ta ard-ennymyn mearagh er nyn giartaghey, as ta jeeaghyn tokens freayll y coad caol. Ny sloo dy reddyn dy chaghlaa eddyr, ny sloo dy smooinaghtyn mychione.","f.private.h":"Lhiats, er dty cho-earrooder","f.private.li1":"Ta'n bord roie er dty vashin hene as cha vel eh freggyrt agh uss.","f.private.li2":"Ta DMyn preevaadjagh eddyr sleih ayns coad follit veih kione gys kione.","f.private.li3":"Gyn coontyn, gyn trackeryn, gyn cookies.","f.lang.h":"Ayns dty chengey hene","f.lang.p":"Erskyn 120 chengey, veih Ollanish, Bretnish as Shapaanish gys pirat, Yoda as Klingon, lesh caghlaa tappee er-ash gys Baarle son goan ny keirdey.","f.service.h":"Veih smooinaght gys shirveish firrinagh","f.service.p":"Hrog oo red ennagh lesh AI ta sleih jannoo ymmyd jeh nish? Cowree eh myr shirveish as nee'n bord cooney lhiat eh y reill dy mie: prowallyn traa ec obbyr, duillag stayd phobblagh, tecaghtyn lesh coontey screeuit, caghlaaghyn ta feme oc er Go, coipyn-sauchys jeeaghit gagh laa. Ta Cooney ynsaghey dhyt gagh kesmad myr t'ou goll.","msgr.h2":"AI-gile Messenger: dty phossan ayns dty phoggaid","msgr.p1":"Loayr rish dty phossan AI gyn y bord y osley. Loayr rish leeideilee dty phryjeckyn as rish dty chaarjyn, as jeeagh er kesmadyn prowal cart as freggyr ad, ooilley veih dty hellvane.","msgr.p2":"Dy chiangley eh, scan coad QR er dty vord. Y chied cheayrt? Nee co-loayrtys demo caarjagh soilshaghey dhyt mygeayrt.","msgr.when":"Android hoshiaght, as eisht lhieggan eggey son çhellvaneyn as iPhone.","msgr.who":"Leeideilagh dty phryjeck","msgr.b1":"Ta'n kiartaghey son y mod dorraghey aarloo. Vel oo laccal ny kesmadyn prowal?","msgr.b2":"Ta, my sailt!","msgr.b3":"1. Foshil Soiaghyn. 2. Reih Dorraghey. Vel eh jeeaghyn kiart?","tl.aria":"Linney traa veih'n chied cho-loayrtys gys y mapp-raad","tl.h2":"Veih'n chied cho-loayrtys gys ny ta ry-heet","tl.lede":"Laghyn as traaghyn firrinagh, ayns dty chryss-traa hene. Lurg jiu, shen y plan, gyn laa erbee gialdit.","tl.today":"Jiu","tl.planned":"plannit","tl.doing":"ayns obbyr","tl.cards.one":"{n} cart","tl.cards.other":"{n} cart","join.h2":"Gow ayrn","join.lede":"Ta AI-gile goll er troggal ec dooinney quaagh lesh feasag, ta AuDHD echey as paart dy streeuyn rish slaynt e aigney, as ec earroo mooar dy jaagentyn foddeeagh. T'eh preevaadjagh son y traa t'ayn, ayns alpha dooint marish caarjyn. Bare lhiat prowal eh tra vees eh foshlit?","join.btn":"Screeu dty ennym sheese","join.small":"Nee mayd post-l y chur hood, as veg elley","footer.tag":"AI-gile. Gyn trackeryn, gyn cookies, gyn caffee co-chruinnaght shassoo.","footer.licence":"Kied dellal","footer.status":"Stayd","footer.privacy":"Ny freayll mayd","footer.thanks":"Eamyn lesh booise da ChilledChat","form.sending":"Cur…","form.failed":"Cha ren shen obbraghey: prow reesht ny s'anmey.","form.offline":"Cha dod mayd roshtyn AI-gile: prow reesht ny s'anmey.","form.keep":"Cha jean mayd ymmyd jeh shoh agh dy reggyrt dhyt, as eisht scryssee mayd ass eh. Gyn trackeryn, gyn cookies.","form.keepLink":"Ny freayll mayd","interest.title":"AI-gile: insh dou tra vees yn alpha foshlit","interest.description":"Faag dty phost-l dy chlashtyn tra vees alpha ny beta dooint AI-gile foshlit.","interest.h1":"🔔 Insh dou tra vees eh foshlit","interest.lede":"Ta AI-gile ayns roish-alpha dooint. Faag dty phost-l as nee mayd screeu un cheayrt, tra vees ynnyd ayn dhyt.","interest.email":"Dty phost-l","interest.which":"Cre'n prowal?","interest.alpha":"Alpha dooint: moch, garroo, ram caghlaaghyn","interest.beta":"Beta: ny s'shickyr, ny s'anmey","interest.both":"Fer erbee, cre-erbee hig hoshiaght","interest.submit":"Cur mee er y rolley","interest.thanks":"Gura mie ayd! T'ou er y rolley.","licence.title":"AI-gile: kied dellal","licence.description":"Jannoo ymmyd jeh AI-gile ayns dty ghellal? Fenee son kied dellal rouyr.","licence.h1":"📜 Kied dellal","licence.lede":"Jannoo ymmyd jeh AI-gile ec obbyr? Insh dooin quoi oo as cre t'ou jannoo. My t'eh jannoo mie ennagh, ta'n kied rouyr.","licence.company":"Co-heshaght","licence.website":"Ynnyd-eggey","licence.what":"Cre t'ou jannoo","licence.how":"Kys t'eh cooney lesh y theihll","licence.email":"Post-l","licence.submit":"Fenee","licence.thanks":"Gura mie ayd! Nee mayd freggyrt liorish post-l.","status.title":"Stayd AI-gile","status.h1":"Stayd AI-gile","status.quiet":"Ooilley kiune","status.intro":"Vel AI-gile gobbraghey nish? Ta'n duillag shoh jeeaghyn er yn ynnyd-eggey, rheynn buird, eamyn as y lhaadey neose gagh 5 minnid.","status.up":"Gobbraghey (hug eh freggyrt ayns {ms} ms)","status.slow":"Cha dug eh freggyrt da'n jeeaghyn s'jerree, prowal reesht","status.down":"Ass obbyr: cha dug eh freggyrt da ny daa jeeaghyn s'jerree","status.svc.web":"Ynnyd-eggey","status.svc.web.offers":"Yn ynnyd shoh: cre ta AI-gile, as y furriym suim","status.svc.boards":"Rheynn buird","status.svc.boards.offers":"Buird phobblagh, çhaghteraghtyn eddyr caarjyn as cuirraghyn","status.svc.calls":"Eamyn","status.svc.calls.offers":"Coraa, feeshan as rheynn screen ayns AI-gile","status.svc.download":"Lhaadey neose","status.svc.download.offers":"Yn stoalagh Windows as kianglaghyn cuirree","status.checking":"Jeeaghyn…","status.offline":"Cha dod mayd roshtyn y shirveish stayd nish (prowal reesht)","status.updated":"noaghit {ago}","status.justNow":"nish dy jarroo","status.min":"{n} minnid er dy henney","status.hours":"{n} oor er dy henney","status.days":"{n} laa er dy henney","privacy.title":"AI-gile: ny freayll mayd","privacy.h1":"Ny freayll mayd","privacy.lede":"Yn lhieggan giare: agh ny ver oo dooin, as cha nee son traa liauyr.","privacy.only":"Agh ny ver oo dooin: ny t'ou screeu ayns furriym, myr dty phost-l. Veg elley mychione oo.","privacy.sealed":"T'eh sealit dy nagh vod y shirveishagh ain eh y lhaih: ayns dty vrawseyr roish my vaagys eh (er brawseyr ny shinney, cha leah as roshys eh). Cha vod agh y bord ain hene eh y osley.","privacy.server":"T'eh scryssit ass y shirveishagh cha leah as roshys eh y bord ain. Ta red erbee ta foast ayn lurg 30 laa scryssit ass ny-yeih.","privacy.board":"Ta shin freayll eh er y bord ain agh derrey vees shin er reggyrt dhyt, as eisht ta shin scryssey ass eh ayns shen myrgeddin.","privacy.none":"Gyn trackeryn, gyn cookies, gyn anailys.","privacy.local":"Ta dty hengey as dty reih soilshey ny dorraghey fuirraght ayns dty vrawseyr hene. Cha vel ad rieau currit dooin.","privacy.ask":"Bare lhiat eh ve ersooyl ny s'leah? Freggyr yn post-d ain as abbyr shen.","live.h2":"Jeeagh er goll er troggal, bio","live.caption":"Ta gagh cart follit: t'ou fakin cummey yn obbyr, cha nee ny goan.","live.watching.one":"bio: {n} jeeaghyn","live.watching.other":"bio: {n} jeeaghyn","live.last.now":"Va'n cart s'jerree scughit nish dy jarroo","live.last.min.one":"Va'n cart s'jerree scughit {n} minnid er dy henney","live.last.min.other":"Va'n cart s'jerree scughit {n} minnid er dy henney","live.last.hour.one":"Va'n cart s'jerree scughit {n} oor er dy henney","live.last.hour.other":"Va'n cart s'jerree scughit {n} oor er dy henney","live.last.day.one":"Va'n cart s'jerree scughit {n} laa er dy henney","live.last.day.other":"Va'n cart s'jerree scughit {n} laa er dy henney","live.offline":"Ta'n bord bio goaill fea veg. Tar er-ash dy gerrid.","live.cols":"Backlog|Dy yannoo|Ayns obbyr|Yn possan jeeaghyn|Dhyts dy phrowal|Son y possan|Jeant","pitch.words.two":"{n} fockle","pitch.words.few":"{n} fockle","pitch.letters.two":"{n} lettyr","pitch.letters.few":"{n} lettyr","pitch.chars.two":"{n} caractar","pitch.chars.few":"{n} caractar","count.line.html.two":"{n} cart er y bord nish","count.line.html.few":"{n} cart er y bord nish","tl.cards.two":"{n} cart","tl.cards.few":"{n} cart"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Currit-magh."]},{"n":2,"texts":["Kanban robotagh.","Jaagenyn, aarloo.","Smooinaghtyn, troggit."]},{"n":3,"texts":["Kanban son robots.","Smooinaghtyn dy ghoo.","Kanban jaagent, seyr."]},{"n":5,"texts":["Bord kanban rollit liorish jaagenyn.","Screeu cartyn. Troggee jaagenyn.","Seyr, logalagh, jeeaghit, red beg ommijagh."]},{"n":8,"texts":["Bord kanban seyr raad ta jaagenyn AI obbraghey.","Screeu smooinaght. Troggee jaagenyn eh. Ghow oo rish.","Agile son un dooinney as ymmodee robots foiljagh."]},{"n":13,"texts":["Bord kanban er dty chooid-earrooder raad ta jaagenyn AI goaill ny cartyn.","Screeu smooinaght. Troggee possan jaagenyn eh. Nee tester eh y yeeaghyn.","Seyr, cha vel coontyn ny trackeryn: bord, paartey dy robots, as oo hene er y chione."]},{"n":21,"texts":["Ta AI-gile bord kanban son obbraghey lesh jaagenyn coadaghey AI. Ta'd goaill ny cartyn; t'ou geaishtagh as goaill rish.","Ta leeideilagh as possan jeh jaagenyn AI ec dy chooilley phryjeck. Screeu gaghlin er cart erbee as ta'n possan goaill toshiaght dy obbraghey.","Bord dy-yannoo pearsoonagh, seyr, ta roie er dty chooid-earrooder hene. She robots ny obbraghee. She oo hene yn fer ta gra ta."]},{"n":34,"texts":["Ta oo cur smooinaghtyn er bord. Ta possan jeh jaagenyn AI cur ad ayns reddyn obbraghey, jeeaghyn ad, as cur ad back dhyts lesh kemmeeyn dy hoiaghey. Cha vel nhee erbee jeant derrey t'ou gra eh.","Ta AI-gile bord kanban troggit ec thie ec Rich lesh ymmodee cooney veih ny jaagenyn ta eh nish rolley. Te seyr, ta eh roie er dty chooid-earrooder, as te rannit rish carryn, cha nee creckit.","Smooinee er bord kanban cadjin, lesh colooyn veih Backlog gys Jeant, agh ta jaagenyn AI goaill ny cartyn. Ta'd cur lieh-lioar er cheayrt, fyssaghey tra t'ad fo-ghooinney, as ta'd fieau dy kinjagh er dty ghoo-ayrn."]},{"n":55,"texts":["Ta AI-gile bord kanban raad ta'n possan jeant jeh jaagenyn AI. Ta leeideilagh ec dy chooilley phryjeck ta plaanal yn obbyr as ynseyderyn ta troggal eh. Tra ta red aarloo, ta tester AI gerjagh eh as goaill screenshot, eisht ta eh cheet gys dty chrink. Gow rish eh, ny screeu gaghlin as nee ad jannoo eh reesht.","Haghyr eh myr raad un pherson dy yeeaghyn ymmodee shessanyn coadaghey AI ec un cheayrt, as dy-yannoo daaghey eh dy ve bord kiart. Ta eh roie er dty vashin, cha vel eh shirrey coontys, as cha vel trackeryn echey. Te seyr son carryn as pobble feaysagh. Te neu-hie neesht, shen-y-fa jean shilley rish gaaue as surprise ayns ynnydyn.","Shoh yn lane onneyr. Ta feme ort foast smooinaghtyn y ve ayd, as feme ort foast jeeaghyn ny toyrtyssyn. Ny ta AI-gile jannoo she dy chooilley nhee eddyr y daa: te freayll ny cartyn ayns oardagh, doostey yn jaagent kiart tra t'ou screeu gaghlin, soilshaghey dy kiart cre ta caghlaait, as freayll dy chooilley nhee ayns un chrink giarrey dhyts."]},{"n":89,"texts":["Ta AI-gile bord kanban seyr t'ou roie er dty chooid-earrooder hene. Ayns ynnyd pobble, ta possan jeh jaagenyn AI ec dy chooilley phryjeck: leeideilagh ta cur dty smooinaghtyn ayns cartyn as plaan, as ynseyderyn ta goaill ny cartyn ayns oardagh ard-phrimmys. Tra ta red troggit, ta tester AI geaishtagh ny kemmeeyn test as soilshaghey dhyts cre honnick eh. Eisht ta eh fieau ayns un chrink enmyssit Dhyts. T'ou goaill rish eh, ny screeu gaghlin as ta'n possan goaill trial elley. Cha vel nhee erbee cheet gys Jeant erbee dty heshaght.","Ta paartey dy reddyn nagh vod oo shilley rish. Ta shilley oie freayll y cholloon Dy yannoo lane choud as t'ou 'sy ruggyr, reih cartyn nagh vel feme ec ny freggyrt veih dyts. Ta earrooder token soilshaghey cre va ymmydit ec ny jaagenyn jiu as yn chemmeeys shoh, as ta No Token Mode gra roo scuirr dy chaiyn. Foddee oo screeu gys carryn, as ta screeuyn pryveyt enmyssit veih kione gys kione. Ta'n bord loayrt mychione 120 chengey, as Ollanish, Flemish, pirat as Klingon cooidjagh. Cha vel nhee jeu ayns jerrey cost er pene, as cha vel dooinney erbee shirrey dy chreck eh dhyts.","Ta AI-gile pryjeck beg, pearsoonagh, cha nee co-heshaght. V'eh dty ghraih Rich dy yannoo kiarail jeh ymmodee phryjeckyn coadaghey AI gyn dy hoshlit dy chooilley appey dy yeeaghyn orroo, myr shen hug eh hene as ny jaagenyn bord son shen, as eisht ghow ad ymmyd jeh'n bord dy hroggal ny va faagit. Te ayns roie-alpha dooint, shen dy ghra te goll er, dy mie, son dorrys dy charrey. Cha vel duillag brisht, cha vel screeuyn-naight, as cha vel plaan gaase. My ta eh jeeaghyn dy ve ymmydagh, foddee oo shirrey dy hoiaghey eh tra vees eh foshlit ny s'ooilley."]},{"n":144,"texts":["Ta AI-gile bord kanban son un dooinney as ymmodee jaagenyn AI. Te roie er dty chooid-earrooder hene as te dy-lhieggan seyr. T'ou cur pryjeckyn lesh, as ta leeideilagh as possan veg ec dy chooilley phryjeck. T'ou loayrt rish y leeideilagh, goll rish Discord, as taggloo mychione smooinaght; ta'n leeideilagh cur eh ayns cartyn as plaan, eisht fieau erriu dy hrimmey Go. Ta'n possan goll trooid ny cartyn ayns oardagh ard-phrimmys, lesh linney-currym aashagh jeant son ard-eie chengey. Roish my jig red erbee back dhyts, ta tester AI geaishtagh ny kemmeeyn ayns coip jeh'n appey as cur screenshot rish. Ta obbyr jeant cheet gys dty chrink lesh ny coadanyn caghlaait as y diff. T'ou goaill rish eh, ny faagail gaghlin as ta'n possan doostey as goaill trial reesht. Cha vod agh oo hene cart y hoiaghey gys Jeant.","Laa lesh AI-gile, kiart dy chooilley. Anmeeragh t'ou faagail paartey dy ghaghlinyn: ta'n cliklee shoh 'sy ynnyd cairal, lhisagh yn rolley shen ve currit ayns oardagh, vod mayd jannoo reihys dorraghey. T'ou goll dy heillagh. Ta ny jaagenyn lhaih ny gaghlinyn, jannoo ny caghlaaghyn, jeeaghyn ad as cur ad back dhyts. My ta Dy yannoo goll follym, ta shilley oie lhieeney eh veih'n backlog lesh cartyn nagh vel feme ec freggyrt veih dyts. Moghrey, ta un chrink giarrey ayn: daa ny three fyssyn as paartey dy reddyn dy hoiaghey, gagh un lesh kemmeeyn oddys dooinney cadley leeideil as screenshot jeh goll er. T'ou cliklee trooid, goaill rish ny mie as cur back ny vooarey. Ta earrooder token soilshaghey cre va ymmydit, as ta No Token Mode ayn son hiaghtynyn caol. Eisht t'ou goaill bee-moghrey, nagh vod ny jaagenyn cooney lesh foast.","Ec toshiaght, cre nagh nee AI-gile. Cha nee startup eh, cha vel eh son creck, as cha vel dooinney erbee cruinnaghey dty ghata. Te bord seyr ta roie er dty chooid-earrooder, gyn coontyn, gyn trackeryn as gyn cookies. Cre te: un ynnyd aarloo dy akin dy chooilley phryjeck coadaghey AI dy-cheilley, lesh possan jaagenyn jannoo ny cartyn as oo hene jannoo ny reihyn. Ta eh cur cartyn giarrey cooidjagh, kerraghey ennymyn ghoill, as freayll shilley er cre cha caol ta'n coad cummal. Ta eh loayrt mychione 120 chengey, veih Ollanish as Flemish gys pirat as Klingon. Foddee carryn screeu da cheilley, pryveyt as enmyssit. Hug Rich as ymmodee jaagenyn foiljagh eh seose, ymmydagh jeh eh hene sheean. Te ayns roie-alpha dooint, myr shen te garroo ayns ynnydyn. My ta eh jeeaghyn dy ve gaue, eam dy mie as foddee oo cheet stiagh moal."]}],"quips":{"1":"Un fockle. Dennal. Foddee dy chooid ro vooar.","3":"Three focklyn. Er-lhiam ny s'onneyr na ymmodee duillagyn bree.","8":"Hoght focklyn. Foast giarey na stand-up.","21":"She points skeealley ny lhiurideyn, my sailliu. Dy bragh.","55":"Queig as queig-jeig focklyn. Ve daa chart jeant choud as v'ou lhaih shen.","144":"Shen yn lhiurid hrooid. Cha vel 233 ayn. Ta ny jaagenyn er gheddyn dy cadley."}},"timeline":{"first-idea.name":"Yn chied smooinaght","first-idea.line":"Yn chied resooney, roish my row coad erbee ayn.","first-board.name":"Yn chied bord","first-board.line":"Bord ta jeeaghyn er e hroggal hene: cartyn, colooyn, tayrn as tilgey, pryjeckyn.","team-roles.name":"Possan as rolleyn","team-roles.line":"Pryfilyn jaagent, tempeljyn possan, ynnydyn as quoi ta jannoo cre.","install.name":"Soiaghey as cur-magh","install.line":"Zip oddys carrey y hoiaghey, nuaghey-hene, rheynnyn as shaghey back.","usage-saver.name":"Sauail ymmyd","usage-saver.line":"Mooadee cre ta roieyn costal, freayll y coad caol, sauail dty chordail.","friends.name":"Carryn as rannagh","friends.line":"DMyn pryveyt, relay enmyssit, cuirrey, rolleyn as pryjeckyn rannit.","languages.name":"Chengaghyn","languages.line":"Dy chooilley screeuyn screen ayns coadan chengey, lesh Ollanish as Flemish er toshiaght.","ai-tester.name":"Tester AI","ai-tester.line":"Ta tester jeeaghyn dy chooilley chur-trooid ec toshiaght as soilshaghey cre honnick eh.","website.name":"Yn ynnyd-eggey","website.line":"aigile.lol, y teaser as y linney-traa shoh.","streaming.name":"Resooney as streaming","streaming.line":"Discord, Twitch, OBS, reihys streamer, GIFs as emojis.","no-ai.name":"Cur-magh gyn AI","no-ai.line":"Bord son sleih ta coadaghey gyn AI, as bordyn poblagh.","night-watch.name":"Shilley oie","night-watch.line":"Ta fer-faghey as Scrum Mainshter freayll ny possanyn er yn obbyr choud as t'ou 'sy ruggyr.","p-more.name":"Dy chooilley nhee elley","p-more.line":"Smooinaghtyn sloo ta fieau foast er nyn gooyl.","p-android.name":"Fone as Android","p-android.line":"Cosney dty bord veih fone, eisht appey Android dooghyssagh.","p-release.name":"Alpha as ny s'anmey","p-release.line":"Alpha dooint, y ynnyd bio, eisht beta.","p-languages.name":"Ny sodjey chengaghyn","p-languages.line":"130 çhengey, as aght-thummey son lheid as ta gynsaghey.","p-engines.name":"Ny sodjey ard-eaynyn AI","p-engines.line":"Reih Claude, Codex, Gemini, Copilot ny Cursor son dagh jaagent.","p-pro.name":"Cliaghtey pro","p-pro.line":"Lioaryn ghaue, dorrysyn merge, cartyn tarmaynyn as raillyn-coadey.","p-self.name":"Tayrn kiarail ort hene","p-self.line":"Reihys skee, cooinaghtynyn hene-kiarail as 4:20.","p-servers.name":"Servaneyderyn as scale","p-servers.line":"Soiaghyn server cooidjagh, rolleyn as plaanal son gaase.","p-livestream.name":"Reddyn streaming elley","p-livestream.line":"Chat Twitch, emojis custom as shilley bio poblagh."},"words":{"button":"📖 Goan ny keirdey","h":"📖 Goan mynit","intro":"Ny goan ver oo er ayns AI-gile, ayns goan aashagh: troggal eh, caghlaa eh dy sauchey, freayll eh goll son y sleih ta jannoo ymmyd jeh, as gobbraghey myr possan lesh AI.","search":"Shir fockle…","none":"Cha vel fockle erbee cordail rish shen.","close":"Dooney","count":{"one":"{count} goo","other":"{count} goan"},"groups":[{"id":"build","name":"🛠️ Troggal eh"},{"id":"change","name":"🔀 Caghlaa eh dy sauchey"},{"id":"run","name":"🛎️ Reill shirveish"},{"id":"team","name":"🤝 Gobbraghey myr possan (as lesh AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Pillagh coad y phryjeck as e hennaghys slane dy commits, freayllit dy cadjin er GitHub myrgeddin.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linney scarrit dy obbyr 'sy choad, dy vod caghlaaghyn ve jeant gyn bentyn rish y phrimlhieggan.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Jalloo sauailt jeh'n choad, lesh note giare mychione cre ren caghlaa. Foddee oo goll er-ash gys fer dy kinjagh.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Cur jallooyn sauailt (commits) veih'n co-earrooder shoh seose gys GitHub, dy vel coip-sauchys jeu as ad rheynnit."},{"id":"merge","g":"build","word":"Merge","text":"Cur caghlaaghyn branch er-ash stiagh 'sy phrimlhieggan."},{"id":"pr","g":"build","word":"Pull request","text":"Fenaght dy vel caghlaaghyn branch er nyn jeeaghyn as er nyn gur stiagh 'sy phrimlhieggan.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Glenney yn coad gyn caghlaa ny t'eh jannoo: coadanyn ny s'lhee, ennymyn ny s'baghtal, ny sloo jannoo-reesht."},{"id":"bug","g":"build","word":"Bug","text":"Red nagh vel gobbraghey myr lhisagh eh.","also":["bugs"]},{"id":"test","g":"build","word":"Prowal","text":"Prowal obbyr jeant dy akin dy vel eh jannoo ny va er ny eysht, roish my gow oo rish.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Giare son quality assurance: ny prowallyn hene-obbragh ta roie roish my hed red erbee bio. Tra ta QA jiarg, hie red ennagh rongagh, as cha vod eh goll bio derrey vees shen kiartit.","also":["prowallyn cairys","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Cur lhieggan noa bio, m.s. er shirveishagh raad ta sleih jannoo ymmyd jeh."},{"id":"release","g":"change","word":"Release","text":"Baggey enmyssit dy obbyr jeant ta goll bio cooidjagh, lesh noteyn giare er ny ren caghlaa. Ta 🚀 Releases screeu ny noteyn veih ny cartyn jeant.","also":["releases","lhieggan"]},{"id":"rollback","g":"change","word":"Roll back","text":"Goll er-ash gys y lhieggan s'jerree va gobbraghey tra ta lhieggan noa jannoo trubbyl. Ayns AI-gile, t'eh jannoo rolley-jeeaghyn jeh ny kesmadyn goll er-ash screeuit er gagh caghlaa.","also":["rollback","roll-back","cur er-ash"]},{"id":"live","g":"change","word":"Bio","text":"Y lhieggan firrinagh ta sleih jannoo ymmyd jeh, cha nee coip son prowal reddyn. Ta coadee gra production rish myrgeddin.","also":["production","live"],"noTip":1},{"id":"change","g":"change","word":"Caghlaa","text":"Caghlaa plannit er red ennagh ta sleih croghey er, screeuit sheese hoshiaght: cre, cre'n fa, y gaue, cuin, as kys dy gholl er-ash er. Toshee fer lesh 🔀 Trog caghlaa.","also":["caghlaaghyn","change request"],"noTip":1},{"id":"risk","g":"change","word":"Gaue","text":"Red ennagh oddagh goll rongagh, lesh scoar er cre cho cosoylagh as cre cho olk as veagh eh. Ta ⚠️ Gauaghyn freayll ad ayns un rolley, yn scoar syrjey hoshiaght, gagh fer lesh date dy yeeaghyn er reesht.","also":["gauaghyn","gaue","risk register"]},{"id":"chgwin","g":"change","word":"Uinnag caghlaa","text":"Ny traaghyn tra oddys caghlaaghyn goll bio, myr fastyr Jemayrt kiune. Mooie jeh uinnag cha vod cart caghlaa ve cooilleenit, mannagh nee eignys t'ayn.","also":["uinnagyn caghlaa","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Vote tappee roish my hed caghlaa bio: ta gagh peiagh ta feme er goaill rish gra Go ny No go. Cha jed eh er agh tra t'ad ooilley cordail.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Coardail","text":"Fuirraght son \"ta\" roish my hoshiaghys yn obbyr. Ta cart ta carrey troggal, ny caghlaa, fuirraght ayns ✅ Coardailyn derrey ver oo dty OK ny obbys oo eh.","also":["coardailyn","approval"]},{"id":"quiettime","g":"change","word":"Traa kiune","text":"Tammylt dy hraa, myr stream, demo ny yn oie, tra nagh jed veg bio. Ta ny possanyn tannaghtyn gobbraghey as prowal, agh ta goll bio fuirraght derrey vees eh harrish. Ayns ynnydyn elley t'eh enmyssit change freeze.","also":["traaghyn kiune","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Red ennagh hrog oo ta sleih croghey er, myr ynnyd-eggey ny app, as kiarail er ny ghoaill jeh dy vod eh tannaghtyn gobbraghey. Cur tick er \"Ta'n pryjeck shoh ny hirveish\" as insh cre t'eh dy hebbal, quoi ta jannoo ymmyd jeh as quoi ta er-cheau.","also":["services"]},{"id":"uptime","g":"run","word":"Prowal uptime","text":"Prowal hene-obbragh, gagh paart dy vinnidyn, dy vel dty hirveish foast freggyrt. My t'eh failleil paart dy keayrtyn fer lurg fer, ta AI-gile fosley cart tecaght er e hon hene.","also":["uptime","prowallyn uptime"]},{"id":"statuspage","g":"run","word":"Duillag status","text":"Duillag phobblagh ta soilshaghey vel shirveish gobbraghey (glass, oranse ny jiarg) lesh y naight s'noa, dy vod y sleih ta jannoo ymmyd jeh jeeaghyn er ayns ynnyd jeh fenaght.","also":["duillagyn status","status page"]},{"id":"desk","g":"run","word":"Deisk shirveish","text":"Raad ta feyshtyn as coontyssyn veih'n sleih ta jannoo ymmyd jeh dty hirveish cheet stiagh. Ta AI-gile cur gagh fer ayns aghin, tecaght ny smooinaght, as t'eh gra shen tra t'eh jeeaghyn myr red ennagh va coontit hannah.","also":["deiskyn shirveish","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Aghin shirveish","text":"Peiagh ennagh fenaght son red cadjin, myr coontey noa ny paart dy chooney, ayns ynnyd jeh insh dy vel red ennagh brisht. T'eh fuirraght son e cheayrt; ta tecaght goll hoshiaght.","also":["aghinyn shirveish","service request"]},{"id":"incident","g":"run","word":"Incident","text":"Red ennagh ta brisht son y sleih ta jannoo ymmyd jeh nish, myr yn ynnyd-eggey ve ass obbyr. Ta cart 🔥 tecaght goll roish y streeu: t'eh y chied red dy gheddyn eh gobbraghey reesht.","also":["incidents","taghyrt"]},{"id":"major","g":"run","word":"Incident mooar","text":"Tecaght feer vooar: ymmodee sleih bentyn rish, ny argid ny data ayns gaue. Ta un chramman cur dy chooilley phossan er (swarm), doostey quoi erbee ta er-cheau as fenaght son naight stayd gagh 30 minnid.","also":["incidents mooarey","toshiaght mooar","major incident"]},{"id":"oncall","g":"run","word":"Er-cheau","text":"Ve yn fer ta freggyrt tra ta red ennagh brishey, eer 'syn oie. Ta oltey possan er-cheau ec gagh shirveish ta doostit hoshiaght son ny tecaghtyn echey.","also":["on call"]},{"id":"replyby","g":"run","word":"Traa freggyrt","text":"Cre cho liauyr as oddys cart fuirraght son y chied reggyrt, son sampleyr oor son tecaght. Lurg shen ta clag jiarg echey, dy nagh bee veg jarroodit dy kiune. T'eh enmyssit response target myrgeddin.","also":["traaghyn freggyrt","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Shilley giare er-ash lurg tecaght: cre haghyr, cre ren cooney as cre lhisagh caghlaa, gyn cur y foill er peiagh erbee. Cha vod tecaght ve dooint fegooish fer.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Doilleeid","text":"Yn oyr follit cooyl jeh un tecaght ny ny smoo. Ta cart 🧩 doilleeid chaglym tecaghtyn ta cheet er-ash dy kinjagh, dy vod yn oyr ve feddynit as kiartit son dy bragh.","also":["doilleeidyn","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Bun-oyr","text":"Yn oyr firrinagh ren red ennagh brishey, cha nee agh ny honnick oo goll rongagh. Kiartee yn bun-oyr as cha jig y tecaght er-ash.","also":["bun-oyryn","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"Aght dy reayll reddyn gobbraghey derrey vees y kiartaghey firrinagh aarloo, myr cur red ennagh er reesht tra t'eh er hassoo. T'eh screeuit er y chart doilleeid dy nagh bee orrin peiagh erbee dy obbraghey magh eh reesht.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Marran enmyssit","text":"Doilleeid ta'n oyr eck er ny hoiggal as ta aght mygeayrt eck, agh nagh vel kiartit foast. Ta 🧩 Marranyn enmyssit cur rolley jeu, dy jean dy chooilley pheiagh ymmyd jeh'n aght mygeayrt ayns ynnyd jeh cleiy reesht.","also":["marranyn enmyssit","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Saraghyn kesmad er kesmad son kiartaghey sorch trubbyl ta fys orrin er, dy vod eh ve jeant er yn aght cheddin, dy tappee, gagh keayrt. Lurg tecaght vooar, foddee yn possan fer y chur roish dhyt son OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Red corys","text":"Un red ta dty hirveish croghey er, myr shirveishagh, ennym-ynnyd, certificate, ogher ny soilleyder. Ta 🗂️ Reddyn corys cur rolley jeu son gagh shirveish, dy vod oo fakin cre ta tecaght bentyn rish as cre ta feme er noaghey ny coip-sauchys.","also":["reddyn corys","configuration item"]},{"id":"expiry","g":"run","word":"Date jerrey","text":"Ta AI-gile freayll arrey er dateyn myr tra ta certificate ny ennym-ynnyd goll ass bree. Cheu-sthie jeh 30 laa roish y date, t'eh jannoo un chart dy noaghey eh, dy nagh scuirr veg gobbraghey dy doaltattym.","also":["dateyn jerrey","jerrey","arrey er dateyn jerrey"]},{"id":"backup","g":"run","word":"Coip-sauchys","text":"Coip sauailt jeh dty data veih roie, dy hoit er-ash er my ta red ennagh caillt ny jeeghit. Ta AI-gile jannoo coip-sauchys jeh dty vuird gagh laa.","also":["coipyn-sauchys","backup","backups"]},{"id":"restore","g":"run","word":"Aa-hoiaghey","text":"Cur data er-ash veih coip-sauchys. Cha vel coip-sauchys coontit dy firrinagh derrey ta fys ayd dy vod eh ve aa-hoit, myr shen t'eh feeu prowal eh nish as reesht.","also":["aa-hoit","restore"]},{"id":"svcreview","g":"run","word":"Scrudeyrys shirveish","text":"Shilley er-ash er un vee jeh shirveish: tecaghtyn foshlit as kiartit, cre cho tappee as hooar sleih freggyrt, traa ec obbyr as tokens ymmydit. Ta'n Scrudeyrys mee soilshaghey eh son gagh shirveish.","also":["scrudeyryssyn shirveish","scrudeyrys mee","service review"]},{"id":"accessreview","g":"run","word":"Scrudeyrys roshtyn","text":"Jeeaghyn gagh 90 laa quoi oddys goll stiagh foast: kianglaghyn rheynn, ayrnyn caarjyn as reddyn follit freayllit. T'ou freayll ny scughey ass gagh fer, dy nagh jean shenn roshtyn tannaghtyn.","also":["scrudeyryssyn roshtyn","access review"]},{"id":"improvements","g":"run","word":"Rolley lheiys","text":"Dy chooilley nhee ren y possan reaghey dy ve ny share ayn, ayns un ynnyd: coyrleyn retro, gniomyn scrudeyrys as kiartaghyn doilleeid, gagh fer lesh y stayd echey. Fow eh fo 📈 Lheiys.","also":["rolleyn lheiys","lheiys"]},{"id":"tokencap","g":"run","word":"Cagliagh tokens","text":"Cagliagh 'sy vee er ny tokens oddys jaagentyn shirveish ymmyd. Ec 80% t'ou geddyn rabbagh; ec 100% ta'n obbyr 'sy background oc fuirraght derrey yn nah vee ny derrey ver oo yn cagliagh seose.","also":["cagliaghyn tokens","token cap"]},{"id":"backlog","g":"team","word":"Backlog","text":"Smooinaghtyn as obbyr nagh vel er ny phlannal foast. Cha bee veg ayns shen er ny obbraghey derrey hed eh gys Dy yannoo."},{"id":"sprint","g":"team","word":"Sprint","text":"Tammylt giare dy obbyr (dy cadjin shiaghtin ny jees) lesh sett dy chartyn er ny choardail dy chooilleeney.","also":["sprints"]},{"id":"standup","g":"team","word":"Co-chruinnaght shassoo","text":"Co-chruinnaght tappee: cre ren dy chooilley oltey, cre nee ad nish, as cre ta lhiettal ad.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Bord lesh collooyn (Dy yannoo, Ayns obbyr, Jeant) raad ta cartyn goll veih'n laue chiare gys y laue yesh myr ta'n obbyr taghyrt."},{"id":"wip","g":"team","word":"Cagliagh WIP","text":"Obbyr fo laue: yn earroo smoo dy chartyn lhisagh ve ayns colloo, dy jean y possan reddyn y chooilleeney roish my hoshiaght ad er ny smoo.","also":["WIP"]},{"id":"dod","g":"team","word":"Kys ta Jeant jeeaghyn","text":"Rolley-jeeaghyn giare y phossan er cre ta \"jeant\" dy ghra, myr prowit as mynit, roish my vees cart currit dhyt. Ta'n sheshey echey, Kys ta Aarloo jeeaghyn, gra cuin ta cart baghtal dy-liooar dy hoshiaght.","also":["Definition of Done","Kys ta Aarloo jeeaghyn","Definition of Ready"]},{"id":"testpile","g":"team","word":"Carn prowal","text":"Ny cartyn jeant ta fuirraght ort dy phrowal, fer lurg fer. Gow rish fer ny cur er-ash eh lesh note, as ta’n nah fer cheet seose.","also":["carnyn prowal","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Shilley er-ash er kys ta'n possan gobbraghey, dy choardail er un red dy yannoo ny share. Ayns AI-gile, ta retro cur caghlaa roish er aghtyn obbyr y phossan, as t'ou gra Go ny Cha nel foast.","also":["retros","retrospective"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Daa hooill elley: ta AI elley jeeaghyn er obbyr gagh cart roish my roshys eh oo, dy jig ny sloo marranyn trooid.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Dy chooilley laue er y deck: ta gagh possan faagail obbyr elley dy chooney lesh un phryjeck erreeishagh derrey vees eh reaghit. Ta pryjeckyn elley fuirraght 'sy traa cheddin.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Yn fer ta freayll yn obbyr goll: t'eh fakin cartyn er hassoo, brodey ny possanyn as cur cooinaghtyn dhyt er ny ta fuirraght. Ayns AI-gile, ta'n Leeideilagh Scrum Mainshter jannoo shoh ayns dy chooilley phryjeck.","also":["Leeideilagh Scrum Mainshter","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Jaagent","text":"AI ta gobbraghey er e hon hene er obbyr: t'eh lhaih yn coad, jannoo caghlaaghyn, roie prowallyn, as ginsh er-ash.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Yn unnid ta ymmyd AI coontit ayn: mysh paart dy lettyryn dy heks lhaiht ny screeuit. Ny sloo dy tokens, ny smoo jeh dty phlan faagit.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Sarey beg ta roie er e hon hene ec traa soit, m.s. tra ta seshoon AI toshiaght, dy vod y possan dty ghaghlinyn y chlashtyn.","also":["hooks"]}]}};
